const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho',
  'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const LINHA = '┈┈┈┈┈┈┈┈┈┈┈┈┈┈';

const emParagrafos = (texto) => texto
  .split(/\n+/)
  .map(paragrafo => paragrafo.trim())
  .filter(Boolean)
  .join('\n\n');

const resp = $input.first().json;
const resumoTopicos = emParagrafos(resp.content?.[0]?.text?.trim() || 'Não foi possível gerar o resumo hoje.');
const stats = $('Calcular estatísticas').first().json;

const hoje = $now;
const dataExtenso = `${DIAS[hoje.weekday % 7]}, ${hoje.day} de ${MESES[hoje.month - 1]}`;

const mensagemFinal = [
  '*📋 Resumo do dia*',
  `_SEU GRUPO AQUI · ${dataExtenso}_`,
  '',
  LINHA,
  '',
  '*🗣️ Tópicos discutidos*',
  '',
  resumoTopicos,
  '',
  LINHA,
  '',
  '*🔗 Links compartilhados*',
  '',
  stats.links,
  '',
  LINHA,
  '',
  '*🏆 Top 5 participantes*',
  '',
  stats.top5,
].join('\n');

return [{ json: { mensagemFinal } }];

